/* XAS Lab service worker, generated by scripts/make-sw.mjs for build __VERSION__.
   Pages and route data: network first, so an online visitor always gets the current site.
   Hashed build assets: cache first (their names change whenever their content does).
   The installed app asks for every asset once ("precache-all") so it works offline. */
const VERSION = '__VERSION__';
const BASE = '__BASE__';
const PAGES = __PAGES__;
const ASSETS = __ASSETS__;
const CACHE = 'xas-' + VERSION;

self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(PAGES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', event => {
  event.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(key => key.startsWith('xas-') && key !== CACHE).map(key => caches.delete(key))))
    .then(() => self.clients.claim()));
});

self.addEventListener('message', event => {
  if (event.data && event.data.type === 'precache-all') event.waitUntil(precacheAll(event.source));
});

async function precacheAll(client) {
  const cache = await caches.open(CACHE);
  let failed = 0;
  for (const url of ASSETS) {
    if (await cache.match(url)) continue;
    try { await cache.add(url); } catch { failed++; }
  }
  if (client) client.postMessage({ type: 'precached', version: VERSION, total: ASSETS.length, failed });
}

const ok = response => response && response.ok && response.type !== 'opaque';

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  if (ok(response)) (await caches.open(CACHE)).put(request, response.clone());
  return response;
}

async function networkFirst(request, isPage, allowOpaque = false) {
  try {
    const response = await fetch(request);
    if (ok(response) || (allowOpaque && response.type === 'opaque')) (await caches.open(CACHE)).put(request, response.clone());
    return response;
  } catch (error) {
    const cached = await caches.match(request, { ignoreSearch: isPage });
    if (cached) return cached;
    if (isPage) {
      const fallback = await caches.match(BASE + '/404.html');
      if (fallback) return fallback;
    }
    throw error;
  }
}

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin === self.location.origin) {
    if (!url.pathname.startsWith(BASE + '/')) return;
    if (url.pathname.startsWith(BASE + '/_next/static/')) event.respondWith(cacheFirst(request));
    else event.respondWith(networkFirst(request, request.mode === 'navigate'));
  } else if (url.origin === 'https://fonts.googleapis.com' || url.origin === 'https://fonts.gstatic.com') {
    // The Google Fonts stylesheet is loaded without CORS, so its response is opaque; it is stable, so keep it for offline use.
    event.respondWith(networkFirst(request, false, true));
  }
});
